let worker,job=0;const jobs=new Map();
export function manuscriptJob(payload){
 if(!worker){worker=new Worker(new URL('./manuscript-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{const pending=jobs.get(data.id);if(pending){jobs.delete(data.id);data.error?pending.reject(Error(data.error)):pending.resolve(data.result)}};worker.onerror=()=>{for(const p of jobs.values())p.reject(Error('원고 처리 중 문제가 발생했습니다. 다시 시도해 주세요.'));jobs.clear();worker.terminate();worker=null}}
 return new Promise((resolve,reject)=>{const id=++job;jobs.set(id,{resolve,reject});worker.postMessage({...payload,id},payload.buffer?[payload.buffer]:[])});
}
const fontOptions=key=>Object.entries(FONT_PRESETS).map(([id,f])=>`<option value="${id}" ${key===id?'selected':''}>${f.name}</option>`).join('');
export function stepper(id,label,value,min,max,step,unit=''){return `<label class="number-control"><span>${label}</span><span class="stepper"><button type="button" data-step="${id}" data-delta="-${step}" aria-label="${label} 줄이기">−</button><input id="${id}" aria-label="${label}" type="number" min="${min}" max="${max}" step="${step}" value="${value}"><button type="button" data-step="${id}" data-delta="${step}" aria-label="${label} 늘리기">+</button></span><small>${unit}</small></label>`}
export function bindSteppers(root){root.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>{const input=root.querySelector('#'+button.dataset.step);input.value=String(Math.max(+input.min,Math.min(+input.max,+(+input.value+ +button.dataset.delta).toFixed(2))));input.dispatchEvent(new Event('change'))})}
export function setTypography(element,settings){const t=typography(settings);element.style.setProperty('--reader-size',t.size+'px');element.style.setProperty('--reader-line',t.line);element.style.setProperty('--reader-letter',t.letter+'px');element.style.setProperty('--paragraph-gap',t.paragraph+'em');element.style.setProperty('--paragraph-indent',t.indent+'em')}
