 const rich=$('#rich-manuscript'),text=$('#source-manuscript'),sheet=$('.document-sheet');text.value=c.text;
 const count=()=>{const visible=c.text.replace(/^:::dialogue [a-zA-Z0-9-]+\n/gm,'').replace(/^:::\s*$/gm,'');$('#char-count').textContent=Array.from(visible).length.toLocaleString()+' 자';$('#no-space').textContent='공백 제외 '+Array.from(visible.replace(/\s/g,'')).length.toLocaleString()+'자'};
 const save=()=>{changed();count();$('#draft-status').textContent='저장 중…'};
