 const render=async()=>{const rev=++revision;rich.setAttribute('aria-busy','true');rich.contentEditable='false';try{const html=await manuscriptJob({type:'render',text:c.text,marks:c.marks,characters:b.characters||[],markdown:true});if(rev===revision&&root.contains(rich)){rich.innerHTML=html||'<p><br></p>';prepareBlocks();rich.removeAttribute('aria-busy');rich.contentEditable='true'}}catch(e){rich.contentEditable='true';rich.removeAttribute('aria-busy');toast(e.message)}};
 const mode=async next=>{source=next;range=null;text.hidden=!source;rich.hidden=source;$('#mode-rich').classList.toggle('selected',!source);$('#mode-source').classList.toggle('selected',source);$('#editor-note').textContent=source?'마크다운 문법을 직접 편집합니다.':'서식이 적용된 문서에서 바로 편집합니다.';$('.block-actions').hidden=source;if(source)text.value=c.text;else await render()};
 const snapshot=()=>({text:c.text,marks:structuredClone(c.marks)});let history=[snapshot()],historyIndex=0;
 const checkpoint=()=>{if(history[historyIndex]?.text===c.text&&JSON.stringify(history[historyIndex]?.marks)===JSON.stringify(c.marks))return;history=history.slice(0,historyIndex+1);history.push(snapshot());if(history.length>30)history.shift();historyIndex=history.length-1};
 const effectState=()=>{if(!source)return selectedEffect(rich,range);const {start,end}=selection();if(start===end)return 'none';const edges=[start,...c.marks.flatMap(m=>[m.start,m.end]).filter(n=>n>start&&n<end),end].sort((a,b)=>a-b);const values=edges.slice(0,-1).map((n,i)=>Object.assign({},...c.marks.filter(m=>m.start<=n&&m.end>=edges[i+1]).map(m=>m.attrs)).effect||'none');return values.every(v=>v===values[0])?values[0]:'mixed'};
 const updateEffects=()=>{const effect=effectState();root.querySelectorAll('[data-effect]').forEach(el=>el.setAttribute('aria-pressed',effect==='mixed'?'mixed':String(el.dataset.effect===effect)))};
