 rich.onkeyup=capture;rich.onmouseup=capture;rich.ontouchend=()=>requestAnimationFrame(capture);const abort=new AbortController();document.addEventListener('selectionchange',()=>{if(!root.contains(rich))return abort.abort();capture()},{signal:abort.signal});text.onselect=()=>updateEffects();
