 text.oninput=()=>{c.marks=remapMarks(c.marks,c.text,text.value);c.text=text.value;checkpoint();save()};
 const selection=()=>source?{start:text.selectionStart,end:text.selectionEnd}:null;
 const apply=attrs=>{if(c.marks.length>=400)return toast('회차당 서식은 400개까지 사용할 수 있습니다.');if(source){const {start,end}=selection();if(start===end)return toast('본문에서 문장을 선택해 주세요.');c.marks.push({start,end,attrs});checkpoint();save();updateEffects();return}if(!range||range.collapsed||!rich.contains(range.commonAncestorContainer))return toast('본문에서 문장을 선택해 주세요.');const before=selectionOffsets(rich,range);rich.querySelectorAll('.fx-letter').forEach(el=>el.replaceWith(...el.childNodes));rich.normalize();range=restoreSelection(rich,before)||range;const selected=range.cloneRange(),walker=document.createTreeWalker(rich,NodeFilter.SHOW_TEXT),nodes=[];let node;while((node=walker.nextNode()))if(selected.intersectsNode(node)&&!node.parentElement.closest('[contenteditable="false"]')){const start=selected.startContainer===node?selected.startOffset:0,end=selected.endContainer===node?selected.endOffset:node.length;if(end>start)nodes.push({node,start,end})}if(nodes.length+c.marks.length>400)return toast('선택 범위가 너무 큽니다. 원문 모드에서 적용하거나 범위를 줄여 주세요.');const wrappers=[];for(const item of nodes){const r=document.createRange();r.setStart(item.node,item.start);r.setEnd(item.node,item.end);const template=document.createElement('template');template.innerHTML=formatText('x',[{start:0,end:1,attrs}]);const span=template.content.firstElementChild;span.textContent='';span.append(r.extractContents());r.insertNode(span);wrappers.push(span)}if(wrappers.length){range=document.createRange();range.setStartBefore(wrappers[0]);range.setEndAfter(wrappers.at(-1));const selection=getSelection();selection.removeAllRanges();selection.addRange(range)}const offsets=range?selectionOffsets(rich,range):null;sync();rich.innerHTML=renderManuscript(c.text,c.marks,b.characters||[]);prepareBlocks();range=restoreSelection(rich,offsets);updateEffects()};
 // Preserve the text selection when clicking a toolbar button.
 root.querySelectorAll('.format-toolbar button').forEach(el=>el.onmousedown=e=>e.preventDefault());
 root.querySelectorAll('[data-format]').forEach(el=>el.onclick=()=>{const key=el.dataset.format;let active=false;if(source){const {start,end}=selection();active=c.marks.some(m=>m.start<=start&&m.end>=end&&m.attrs[key]===true)}else if(range){let node=range.startContainer;if(node.nodeType===1)node=node.childNodes[range.startOffset]||node;const element=node.nodeType===1?node:node.parentElement;const style=getComputedStyle(element);active=key==='bold'?+style.fontWeight>=600:key==='italic'?style.fontStyle==='italic':style.textDecorationLine.includes(key==='strike'?'line-through':'underline')}apply({[key]:!active})});
 $('#text-color').onchange=e=>apply({color:e.target.value});root.querySelectorAll('[data-effect]').forEach(el=>el.onclick=()=>apply({effect:effectState()===el.dataset.effect?'none':el.dataset.effect,intensity:+$('#effect-strength').value}));$('#effect-strength').onchange=()=>{const effect=effectState();if(effect!=='none'&&effect!=='mixed')apply({effect,intensity:+$('#effect-strength').value})};
 $('#clear-format').onclick=()=>{if(source){const {start,end}=selection();c.marks=clearMarks(c.marks,start,end);checkpoint();save();return}apply({bold:false,italic:false,underline:false,strike:false,effect:'none',font:c.font,px:c.layout.size,color:'inherit'})};
 $('#chapter-title').onfocus=()=>{range=null;updateEffects();$('#selection-info').textContent='본문을 선택해 서식을 적용하세요.'};
 $('#chapter-adult').onchange=e=>{c.adult=e.target.checked;save()};
 $('#chapter-title').oninput=e=>{c.title=e.target.value;save()};
 $('#chapter-font').onchange=e=>{if(source?text.selectionStart!==text.selectionEnd:range&&!range.collapsed){apply({font:e.target.value})}else{c.font=e.target.value;styles();save()}};
 $('#own-font').onclick=()=>uploadFont(()=>{c.font='custom';$('#chapter-font').value='custom';styles();save()});
 root.querySelectorAll('[data-align]').forEach(el=>el.onclick=()=>{c.align=el.dataset.align;styles();save()});
 for(const [id,key] of [['doc-size','size'],['doc-line','line'],['doc-letter','letter'],['doc-paragraph','paragraph'],['doc-indent','indent']])$('#'+id).onchange=e=>{if(key==='size'&&(source?text.selectionStart!==text.selectionEnd:range&&!range.collapsed)){apply({px:Math.max(12,Math.min(36,+e.target.value))});return}c.layout=typography({...c.layout,[key]:e.target.value});e.target.value=c.layout[key];styles();save()};
 $('#page-width').value=c.width||800;$('#page-width').onchange=e=>{c.width=+e.target.value;styles();save()};$('#page-padding').onchange=e=>{c.padding=Math.min(120,Math.max(16,+e.target.value));e.target.value=c.padding;styles();save()};
 $('#paper-theme').onclick=()=>openSettings();
