 $('#layout-reset').onclick=()=>{c.layout=typography();c.padding=60;c.width=800;for(const [id,key] of [['doc-size','size'],['doc-line','line'],['doc-letter','letter'],['doc-paragraph','paragraph'],['doc-indent','indent']])$('#'+id).value=c.layout[key];$('#page-padding').value=60;$('#page-width').value=800;styles();save()};bindSteppers(root);
 $('#mode-rich').onclick=()=>mode(false);$('#mode-source').onclick=()=>mode(true);
 $('#undo-edit').onclick=()=>{if(historyIndex>0){Object.assign(c,structuredClone(history[--historyIndex]));mode(source);save()}};$('#redo-edit').onclick=()=>{if(historyIndex<history.length-1){Object.assign(c,structuredClone(history[++historyIndex]));mode(source);save()}};
 $('#save-now').onclick=async()=>{await flush();if(root.contains(rich))$('#draft-status').textContent=document.querySelector('#sync-status').textContent};
 $('#markdown-help').onclick=()=>openDialog('<h2>마크다운</h2><p>**굵게** · *기울임* · ~~취소선~~</p><p># 제목 · ## 소제목<br>&gt; 인용문<br>- 목록 · 1. 번호 목록<br>--- 구분선<br>[링크 이름](https://주소)</p><p>빈 줄은 문단 구분, Enter 한 번은 줄바꿈입니다. 원문에서 수정하고 문서 편집이나 읽기 화면에서 확인하세요. HTML, 표 문법, 외부 이미지 문법은 지원하지 않습니다.</p><button class="btn" data-close>닫기</button>');
 $('#import-text').onclick=()=>openImport();
 function openImport(){openDialog(`<h2>원고 가져오기</h2><form id="import-form"><label class="field">TXT / Markdown<input id="import-file" type="file" accept=".txt,.md,text/plain,text/markdown" required></label><label class="field">가져올 위치<select id="import-target"><option value="new">새 회차에 추가</option><option value="replace">현재 회차 교체</option></select></label><label class="field">문자 인코딩<select id="import-encoding"><option value="auto">자동 감지</option><option value="utf-8">UTF-8</option><option value="euc-kr">한글 (EUC-KR)</option><option value="utf-16le">UTF-16 LE</option></select></label><p>최대 18만 자. 큰 원고는 가벼운 원문 편집 모드로 열립니다.</p><p id="import-progress" role="status"></p><div class="dialog-actions"><button type="button" class="btn" data-close>취소</button><button class="btn primary" id="import-submit">가져오기</button></div></form>`);
 document.querySelector('#import-form').onsubmit=async e=>{e.preventDefault();if(importing)return;const file=document.querySelector('#import-file').files[0];if(!file)return;if(file.size>1500000)return toast('파일은 1.5MB 이하로 선택해 주세요.');const target=document.querySelector('#import-target').value,encoding=document.querySelector('#import-encoding').value;if(target==='replace'&&c.text&&!confirm('현재 원고를 교체할까요? 실행 취소로 되돌릴 수 있습니다.'))return;importing=true;const progress=document.querySelector('#import-progress'),submit=document.querySelector('#import-submit');submit.disabled=true;progress.textContent='파일 읽는 중…';try{const buffer=await file.arrayBuffer();progress.textContent='문자 인코딩과 줄바꿈 처리 중…';const value=await manuscriptJob({type:'import',buffer,encoding});if(!document.querySelector('#modal').open||document.querySelector('#import-form')!==e.target)return;if(value.length>180000)throw Error('18만 자를 초과했습니다. 파일을 나누어 가져와 주세요.');if(!root.contains(rich))throw Error('편집 화면이 바뀌었습니다. 다시 가져와 주세요.');if(target==='new'){await flush();const chapter={id:crypto.randomUUID(),title:file.name.replace(/\.(txt|md)$/i,''),text:value,marks:[],font:'kopub',layout:typography(),updated:Date.now()};b.chapters.push(chapter);await changed(chapter);document.querySelector('#modal').close();location.hash='edit/'+b.id+'/'+chapter.id}else{c.text=value;c.marks=[];checkpoint();await mode(value.length>60000);save();await flush();document.querySelector('#modal').close()}toast('원고를 가져왔습니다.')}catch(error){progress.textContent=error.message}finally{importing=false;submit.disabled=false}};
 }
 $('#insert-dialogue').onclick=()=>{b.characters=b.characters||[];openDialog(`<h2>인물 대사</h2><form id="dialogue-form"><label class="field">인물<select id="dialogue-person"><option value="new">새 인물</option>${b.characters.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><div id="new-person"><label class="field">인물 이름<input id="person-name" maxlength="30"></label><label class="field">인물 사진 (선택)<input type="file" id="person-photo" accept="image/png,image/jpeg,image/webp"></label></div><label class="field">대사<textarea id="dialogue-text" required maxlength="5000"></textarea></label><p>사진은 원형으로 표시됩니다. 시리즈당 인물 6명까지 저장할 수 있습니다.</p><div class="dialog-actions"><button type="button" class="btn" data-close>취소</button><button class="btn primary">삽입</button></div></form>`);document.querySelector('#dialogue-person').onchange=e=>document.querySelector('#new-person').hidden=e.target.value!=='new';document.querySelector('#dialogue-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{let id=document.querySelector('#dialogue-person').value;const value=document.querySelector('#dialogue-text').value;if(/^:::/m.test(value))throw Error('대사 안에서 ::: 구분자는 사용할 수 없습니다.');if(c.text.length+value.length+100>180000)throw Error('회차당 최대 18만 자입니다.');if(id==='new'){const name=document.querySelector('#person-name').value.trim();if(!name)throw Error('인물 이름을 입력해 주세요.');if(b.characters.length>=6)throw Error('인물은 시리즈당 6명까지입니다.');const file=document.querySelector('#person-photo').files[0];const photo=file?await imageData(file,true):'';id=crypto.randomUUID();b.characters.push({id,name,photo})}const block='\n\n:::dialogue '+id+'\n'+value+'\n:::\n\n';document.querySelector('#modal').close();if(source){text.setRangeText(block,text.selectionStart,text.selectionEnd,'end');text.dispatchEvent(new Event('input'))}else{rich.focus();if(range&&rich.contains(range.commonAncestorContainer)){const s=getSelection();s.removeAllRanges();s.addRange(range)}else{const r=document.createRange();r.selectNodeContents(rich);r.collapse(false);const s=getSelection();s.removeAllRanges();s.addRange(r)}document.execCommand('insertHTML',false,renderManuscript(block,[],b.characters));sync()}document.querySelector('#modal').close();save()}catch(error){toast(error.message)}finally{button.disabled=false}}};
 let activeBlock=null,dragged=null;
 function blockOf(node){let el=node?.nodeType===3?node.parentElement:node;while(el&&el.parentElement!==rich)el=el.parentElement;return el?.parentElement===rich?el:null}
 function selectBlock(block){activeBlock=block;for(const el of rich.children)el.classList.toggle('block-selected',el===block);$('#block-label').textContent=block?(block.classList.contains('dialogue-block')?'인물 대사':'문단')+' 선택됨 · 손잡이를 끌어 이동':'문단을 선택하세요.';for(const id of ['block-up','block-down','block-delete'])$('#'+id).disabled=!block}
 function prepareBlocks(reset=true){for(const block of rich.children){if(block.matches('hr'))continue;if(block.querySelector(':scope > [data-editor-ui]'))continue;const handle=document.createElement('button');handle.type='button';handle.dataset.editorUi='handle';handle.contentEditable='false';handle.draggable=true;handle.className='block-handle';handle.textContent='⠿';handle.title='문단 이동';handle.setAttribute('aria-label','문단 선택 및 드래그 이동');block.prepend(handle)}if(reset)selectBlock(null)}
 rich.addEventListener('click',e=>selectBlock(blockOf(e.target)));
 rich.addEventListener('dragstart',e=>{if(!e.target.closest('[data-editor-ui]'))return;dragged=blockOf(e.target);selectBlock(dragged);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','galpi-block');});
 rich.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();e.dataTransfer.dropEffect='move';const target=blockOf(e.target);for(const el of rich.children)el.classList.toggle('drop-target',el===target&&el!==dragged)});
 rich.addEventListener('drop',e=>{if(!dragged)return;e.preventDefault();const target=blockOf(e.target);if(target&&target!==dragged){const rect=target.getBoundingClientRect();rich.insertBefore(dragged,e.clientY>rect.top+rect.height/2?target.nextSibling:target);range=null;sync()}for(const el of rich.children)el.classList.remove('drop-target');dragged=null;});
 rich.addEventListener('dragend',()=>{dragged=null;for(const el of rich.children)el.classList.remove('drop-target')});
 for(const direction of ['up','down'])$('#block-'+direction).onclick=()=>{if(!activeBlock)return;const sibling=direction==='up'?activeBlock.previousElementSibling:activeBlock.nextElementSibling;if(sibling){rich.insertBefore(activeBlock,direction==='up'?sibling:sibling.nextSibling);range=null;sync()}};
 $('#block-delete').onclick=()=>{if(!activeBlock)return;activeBlock.remove();range=null;selectBlock(null);sync();if(!rich.children.length)rich.innerHTML='<p><br></p>';prepareBlocks()};
 styles();count();mode(source);
